import React from "react";

const Workoutdetails = ({workout}) => {
    return (
        <div>
            <h1>{workout.exercise}</h1>
            <p>Sets:{workout.sets}</p>
            <p>Reps:{workout.reps}</p>
            <p>Weight(Kg):{workout.weight}</p>
            <p>DropSet:{workout.dropSets.toString()}</p>
        </div>
    );
}
